 for(const [token,ref,job] of [[f.alice.token,a,av],[f.bob.token,b,bv]]){const state=await f.status(token,ref);assert.equal(state.saved,true);assert.equal(state.processed,true);assert.equal(state.indexed,true);assert.deepEqual(state.index,{material:true,memory:false});const material=await f.checked(token,'/api/materials/'+state.materialId+'/read');assert.ok(material.text===bytes.toString());const artifact=await f.checked(token,'/api/processing/artifacts/'+job.result.artifactId);assert.equal(artifact.originalRef,ref);assert.ok((await f.checked(token,'/api/data/search?query=Generated')).items.length>0);}
 assert.equal((await f.request(f.alice.token,'/api/processing/artifacts/'+bv.result.artifactId)).statusCode,404);assert.equal((await f.request(f.alice.token,'/api/processing','POST',{originalRef:b,operationId:'foreign'})).statusCode,404);assert.equal((await f.request(f.admin.token,'/api/processing/originals/'+a.slice(9))).statusCode,404);
 assert.equal(f.read(db=>db.prepare('SELECT count(*) n FROM mp_artifacts').get()!.n),2);assert.equal(f.read(db=>db.prepare('SELECT count(*) n FROM user_model_snapshots').get()!.n),0);
