 const bytes=Buffer.from('equal generated image'),ar=await f.upload(f.alice.token,bytes,'image/png'),br=await f.upload(f.bob.token,bytes,'image/png');const [a,b]=await Promise.all([f.submit(f.alice.token,ar.captures[0].original.ref),f.submit(f.bob.token,br.captures[0].original.ref)]);await until(()=>requests.length===2,'both scoped OCR calls did not enter');assert.deepEqual(new Set(requests.map(r=>r.key)),new Set(['Bearer GENERATED_A','Bearer GENERATED_B']));assert.deepEqual(new Set(requests.map(r=>r.body)),new Set([bytes.toString()]));assert.equal(new Set(requests.map(r=>r.scope)).size,2);assert.ok(requests.every(r=>/^[a-f0-9]{64}$/.test(r.scope)));
 await f.models(f.alice.token,url,'GENERATED_A','current-model');gate.resolve();await Promise.all([f.wait(f.alice.token,a.id),f.wait(f.bob.token,b.id)]);assert.equal(requests.length,2);for(const [token,expected] of [[f.alice.token,'A_OUTPUT'],[f.bob.token,'B_OUTPUT']]){const usage=await f.checked(token,'/api/usage');assert.equal(usage.items.length,1);assert.equal(usage.items[0].operation,'ocr');assert.equal(usage.items[0].model,'same-model');const state=await f.status(token,(token===f.alice.token?ar:br).captures[0].original.ref);const material=await f.checked(token,'/api/materials/'+state.materialId+'/read');assert.ok(material.text.includes(expected));assert.equal(JSON.stringify(material).includes(token===f.alice.token?'GENERATED_B':'GENERATED_A'),false);}
