test('an actual generated custom processor transforms bounded originals and M05 commits only its validated current output',async t=>{
 const code=generatedScopedPluginSource.replace("if(input.method)return host.call(input.method,input.args??[]);",String.raw`
  if(input.transform){
   const original=await host.call('readOriginal',[input.originalRef]);
   const text=configuration.label+': '+Buffer.from(original.bytes.data).toString('utf8').toUpperCase();
   const output=input.invalid?{durationMs:0,segments:[{startMs:10,endMs:0,text}]}:{durationMs:0,segments:[{startMs:0,endMs:0,text}],engine:'generated-installed-transform'};
   const result=await host.call('stageExtraction',[input.originalRef,output]);
   if(input.failAfter)throw Error('GENERATED_PRIVATE_PLUGIN_FAILURE');
   return result;
  }
  if(input.method)return host.call(input.method,input.args??[]);`),release=generatedScopedPluginRelease('33',code),f=await fixture(t,false,release),preview=await f.checked(f.admin.token,'/api/plugins/resolve','POST',{repository:release.repository,tag:release.tag}),catalog=await f.checked(f.admin.token,'/api/admin/plugins'),installed=await f.checked(f.admin.token,'/api/plugins/install','POST',{previewId:preview.id,expectedRevision:catalog.revision,operationId:randomUUID()});await until(()=>f.node.plugins!.catalog.view().packages[0].state==='installed','custom processor did not install');
 const snapshots=new Map<string,string>();for(const [token,label] of [[f.alice.token,'A'],[f.bob.token,'B']]){const view=()=>f.checked(token,'/api/plugins');await f.checked(token,'/api/plugin-instances','POST',{expectedRevision:(await view()).revision,instance:{id:'same-instance',packageId:installed.packages[0].id,name:'Generated custom transform',configuration:{label},desired:false,grants:{capabilities:['processor'],sourceIds:['same-source'],history:false}}});await f.checked(token,'/api/plugin-instances/same-instance/check','POST',{});await f.checked(token,'/api/plugin-instances/same-instance/enable','POST',{expectedRevision:(await view()).revision});snapshots.set(token,(await f.checked(token,'/api/plugin-instances/same-instance/snapshots','POST',{})).id);}
 const bytes=Buffer.from('equal generated payload'),aRef=(await f.upload(f.alice.token,bytes)).captures[0].original.ref,bRef=(await f.upload(f.bob.token,bytes)).captures[0].original.ref,invoke=(token:string,originalRef:string,extra:Record<string,unknown>={})=>f.checked(token,'/api/plugin-snapshots/'+snapshots.get(token)+'/invoke','POST',{componentId:'generated.processor',payload:{transform:true,originalRef,...extra},operationId:randomUUID()});
 for(const [token,ref,label] of [[f.alice.token,aRef,'A'],[f.bob.token,bRef,'B']]){const job=await invoke(token,ref);await f.wait(token,job.id);const status=await f.status(token,ref);assert.equal((await f.checked(token,'/api/materials/'+status.materialId+'/read')).text,label+': '+bytes.toString().toUpperCase());}
 const foreign=await invoke(f.alice.token,bRef);await f.wait(f.alice.token,foreign.id,'blocked');const failedRef=(await f.upload(f.alice.token,bytes,'text/plain','failed-custom')).captures[0].original.ref,failed=await invoke(f.alice.token,failedRef,{failAfter:true});const blocked=await f.wait(f.alice.token,failed.id,'blocked');assert.equal(JSON.stringify(blocked).includes('GENERATED_PRIVATE_PLUGIN_FAILURE'),false);const state=await f.status(f.alice.token,failedRef);assert.deepEqual([state.saved,state.processed,state.indexed],[true,false,false]);const invalid=await invoke(f.alice.token,failedRef,{invalid:true});await f.wait(f.alice.token,invalid.id,'blocked');assert.equal(f.read(db=>db.prepare('SELECT count(*) n FROM mp_artifacts WHERE user_id=? AND original_id=?').get(f.a.userId,failedRef.slice(9))!.n),1);
});

test('the synchronous Material hook admits real M05 consumer grants atomically and they outlive the completed publisher context',async t=>{
 const f=await fixture(t),gate=deferred();t.after(()=>gate.resolve());const publishers:TaskRun[]=[],children:{userId:string;id:string}[]=[],seen:{userId:string;id:string;revision:string;text:string}[]=[];
 f.node.execution!.register({kind:'generated.material-consumer',pool:'generated.material-consumer',concurrency:()=>2,policy:EXECUTION_POLICIES.control,parseInput:value=>z.object({id:z.string(),revision:z.string()}).strict().parse(value),execute:async run=>{await gate.promise;run.grant.assert();const data=run.services.get<PrivateData>('private-data'),id=String(run.task.input.id),revision=String(run.task.input.revision),read=data.readMaterial(id,{revision});seen.push({userId:run.context.userId,id,revision,text:read.text});return {id,revision};}});
 const dispose=f.node.processing!.onMaterialPublished((run,material)=>{publishers.push(run);assert.doesNotThrow(()=>f.node.authority.assert(run.context));const task=f.node.execution!.forUser(run.context).submitSync({kind:'generated.material-consumer',operationId:'material:'+material.id+':'+material.revision,input:material});children.push({userId:run.context.userId,id:task.id});});
 const bytes=Buffer.from('GENERATED_ATOMIC_MATERIAL_HANDOFF');for(const token of [f.alice.token,f.bob.token]){const ref=(await f.upload(token,bytes)).captures[0].original.ref,job=await f.submit(token,ref);await f.wait(token,job.id);}assert.equal(children.length,2);assert.notEqual(children[0].id,children[1].id);for(const run of publishers)assert.throws(()=>f.node.authority.assert(run.context));gate.resolve();for(const child of children)await f.wait(child.userId===f.a.userId?f.alice.token:f.bob.token,child.id);assert.deepEqual(new Set(seen.map(row=>row.userId)),new Set([f.a.userId,f.b.userId]));assert.ok(seen.every(row=>row.text===bytes.toString()));dispose();dispose();
});

