test('caught nested admission failure rolls back every child row while the publishing Material transaction succeeds',async t=>{
 const f=await fixture(t);let caught=0,executions=0;
 f.node.execution!.register({kind:'generated.bad-resource',pool:'generated.bad-resource',concurrency:()=>1,policy:EXECUTION_POLICIES.control,parseInput:()=>({}),resources:()=>[{scope:'invalid' as 'user',key:'generated'}],execute:async()=>{executions++;return null;}});
 f.node.processing!.onMaterialPublished(run=>{try{f.node.execution!.forUser(run.context).submitSync({kind:'generated.bad-resource',operationId:'generated-caught-child',input:{}});}catch{caught++;}});
 const ref=(await f.upload(f.alice.token,Buffer.from('Generated caught admission'))).captures[0].original.ref,job=await f.submit(f.alice.token,ref);await f.wait(f.alice.token,job.id);for(let i=0;i<5;i++)await f.node.execution!.tick();assert.equal(caught,1);assert.equal(executions,0);assert.equal((await f.status(f.alice.token,ref)).indexed,true);
 f.read(db=>{assert.equal(db.prepare("SELECT count(*) n FROM execution_steps WHERE kind='generated.bad-resource'").get()!.n,0);assert.deepEqual(db.prepare('SELECT e.kind FROM user_tasks u JOIN execution_steps e ON e.id=u.task_id ORDER BY e.kind').all().map(row=>row.kind),['memory.intake','memory.materials','memory.materials','processing.extract','processing.pipeline']);assert.equal(db.prepare('SELECT count(*) n FROM task_authorizations').get()!.n,5);assert.equal(db.prepare('SELECT count(*) n FROM user_tasks u LEFT JOIN execution_steps e ON e.id=u.task_id AND e.user_id=u.user_id WHERE e.id IS NULL').get()!.n,0);assert.equal(db.prepare('SELECT count(*) n FROM task_authorizations a LEFT JOIN execution_steps e ON e.id=a.task_id WHERE e.id IS NULL').get()!.n,0);for(const table of ['execution_resources','execution_operation_steps'])assert.equal(db.prepare('SELECT count(*) n FROM '+table+' a LEFT JOIN execution_steps e ON e.id=a.step_id WHERE e.id IS NULL').get()!.n,0);assert.equal(db.prepare("SELECT count(*) n FROM execution_fairness WHERE pool='generated.bad-resource'").get()!.n,0);assert.equal(db.prepare("SELECT count(*) n FROM operation_progress WHERE id LIKE '%generated-caught-child%'").get()!.n,0);assert.equal(db.prepare('SELECT next FROM execution_user_sequence WHERE user_id=?').get(f.a.userId)!.next,5);});
});

