test('original file forgetting removes all owned revisions, blocks resync until explicit allow-again and preserves B',async t=>{
 const f=await fixture(t),bytes=Buffer.from('GENERATED_FORGETTABLE_EXACT_BYTES'),aRef=(await f.upload(f.alice.token,bytes)).captures[0].original.ref,bRef=(await f.upload(f.bob.token,bytes)).captures[0].original.ref;for(const [token,ref] of [[f.alice.token,aRef],[f.bob.token,bRef]]){const job=await f.submit(token,ref);await f.wait(token,job.id);}const a=await f.status(f.alice.token,aRef),b=await f.status(f.bob.token,bRef),path='/api/files/'+a.original.captureId;assert.equal(a.original.captureId,b.original.captureId);const ticket=await f.checked(f.alice.token,'/api/ingress/originals/'+aRef.slice(9)+'/tickets','POST',{mode:'download'});const exportId=randomUUID();await f.checked(f.alice.token,'/api/portable/exports','POST',{operationId:exportId});for(let attempt=0;;attempt++){const state=await f.checked(f.alice.token,'/api/portable/exports/'+exportId);if(state.state==='completed')break;assert.ok(attempt<1000,JSON.stringify(state));await delay(5);}const oldArchive=await f.checked(f.alice.token,'/api/portable/exports/'+exportId+'/content');const result=await forgetFile(f,f.alice.token,path);assert.ok(result.deleted>=1);assert.equal((await f.request(f.alice.token,path)).statusCode,404);assert.equal((await f.request(f.alice.token,'/api/ingress/originals/'+aRef.slice(9)+'/content?ticket='+encodeURIComponent(ticket.ticket))).statusCode,404);assert.equal((await f.checked(f.bob.token,'/api/files/'+b.original.captureId)).sha256,bytesHash(bytes));assert.equal((await f.request(f.alice.token,'/api/processing/artifacts/'+a.artifactId)).statusCode,404);const blockedImport=randomUUID();await f.checked(f.alice.token,'/api/portable/imports','POST',{operationId:blockedImport,archive:oldArchive});for(let attempt=0;;attempt++){const state=await f.checked(f.alice.token,'/api/portable/imports/'+blockedImport);if(state.state!=='working'){assert.equal(state.state,'failed',JSON.stringify(state));assert.equal(state.error,'archive_conflict');break;}assert.ok(attempt<1000);await delay(5);}assert.equal((await f.request(f.alice.token,path)).statusCode,404,'older personal import must not resurrect a forgotten file');await f.restart();assert.equal((await f.request(f.alice.token,path)).statusCode,404);const scope=f.node.services.forUser(await f.node.authority.authenticate(f.alice.token)),tombstones=await scope.exportUser('ingress');assert.equal((tombstones.payload as any).forgottenFiles.length,1);assert.equal((tombstones.payload as any).forgottenFiles[0].blocked,1);await scope.deleteUser('ingress','generated-forget-retention-delete');await scope.restoreUser('ingress',tombstones,'generated-forget-retention-restore');assert.equal((await f.request(f.alice.token,path+'/allow-again','POST',result.decision)).statusCode,409,'data-only restore cannot revive a previously issued allow decision');assert.notEqual((await f.checked(f.alice.token,path+'/forgotten')).decision.decisionId,result.decision.decisionId);
 const manifest={sourceId:'same-source',item:{externalId:'same-file',revision:'same-revision',observedAt:'2026-10-15T00:00:00Z',title:'Generated file',text:'',kind:'file',layer:'original',mimeType:'text/plain'},sizeBytes:bytes.length,sha256:bytesHash(bytes),relativePath:'generated.bin'};assert.equal((await f.request(f.alice.token,'/api/ingress/sources/same-source/uploads','POST',{batchId:'same-file:same-revision',revision:manifest})).statusCode,410);assert.equal((await f.request(f.bob.token,path+'/allow-again','POST',{sourceId:'same-source',externalId:'same-file'})).statusCode,404);await f.checked(f.alice.token,path+'/allow-again','POST',(await f.checked(f.alice.token,path+'/forgotten')).decision);assert.equal((await f.request(f.alice.token,path)).statusCode,404,'allow-again does not recreate content');const newRef=(await f.upload(f.alice.token,bytes)).captures[0].original.ref,newTask=await f.submit(f.alice.token,newRef,'generated-explicit-allow-again');await f.wait(f.alice.token,newTask.id);assert.equal((await f.request(f.alice.token,'/api/ingress/originals/'+aRef.slice(9)+'/content?ticket='+encodeURIComponent(ticket.ticket))).statusCode,404,'an old signed download ticket must not revive after explicit re-import');assert.equal((await f.checked(f.alice.token,'/api/files/'+(await f.status(f.alice.token,newRef)).original.captureId)).sha256,bytesHash(bytes));assert.equal((await f.checked(f.bob.token,'/api/files/'+b.original.captureId)).sha256,bytesHash(bytes));
});

